export function getValidValue<ReturnType = string>(
  value: any,
  format?: (value: any) => ReturnType,
  fallback?: ReturnType
): ReturnType {
  if (value === undefined || value === null || value === '' || value === false) {
    return fallback !== undefined ? fallback : ('-' as ReturnType);
  }

  if (Array.isArray(value) && value.length === 0) {
    return fallback !== undefined ? fallback : ('-' as ReturnType);
  }

  if (typeof value === 'object' && Object.keys(value).length === 0) {
    return fallback !== undefined ? fallback : ('-' as ReturnType);
  }

  if (format) {
    return format(value);
  }

  return value as ReturnType;
}

import type { TimeGranularity } from '../types/date';

/**
 *
 * Format timestamp to detailed date string based on time granularity
 * @param timestamp - ISO timestamp string
 * @param granularity - Time granularity (year, month, week)
 * @returns Formatted date string
 *
 * @example
 * ```ts
 * formatDetailedDate('2024-01-15', 'year')  // "2024"
 * formatDetailedDate('2024-01-15', 'month') // "January 2024"
 * formatDetailedDate('2024-01-15', 'week')  // "Jan 15 - Jan 21, 2024"
 * ```
 */
export function formatDetailedDate(timestamp: string, granularity: TimeGranularity): string {
  const date = new Date(timestamp);

  switch (granularity) {
    case 'year':
      return date.getFullYear().toString();
    case 'month':
      return date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    case 'week': {
      const endDate = new Date(timestamp);
      endDate.setDate(endDate.getDate() + 6);
      return `${date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} - ${endDate.toLocaleDateString(
        'en-US',
        { month: 'short', day: 'numeric', year: 'numeric' }
      )}`;
    }
    default:
      return date.toLocaleDateString('en-US', {
        month: 'long',
        day: 'numeric',
        year: 'numeric',
      });
  }
}

import { format, parseISO, isValid } from 'date-fns';

/** Functions to format dates
 *
 * @example
 * formatDate('2024-12-30T00:00:00Z') // '2024-12-30'
 * @param date - The date to format.
 * @param format - The format to use (date-fns format pattern).
 * @returns The formatted date or empty string if the date is invalid.
 */
export function toLocalDateString(date: string | Date, formatPattern?: string): string {
  try {
    if (!date) return '';

    if (typeof date === 'string' && date.startsWith('0001-01-01')) return '';

    const pdate = new Date(date);
    if (Number.isNaN(pdate.getTime())) return '';

    const parsedDate = parseISO(date as string);
    if (!isValid(parsedDate)) return '';

    return format(parsedDate, formatPattern || 'dd/MM/yyyy');
  } catch (error) {
    console.error(error);
    return '';
  }
}

/**
 * Format date to display locale string
 * @param date - Date string or Date object
 * @param format - Format type (date-fns format pattern)
 * @returns Formatted date string
 * @example
 * formatDate('2024-01-01') // 'Jan 01, 2024 00:00'
 * formatDate(new Date('2024-01-01')) // 'Jan 01, 2024 00:00'
 * formatDate(undefined) // ''
 */
export function formatDate(
  date: string | number | Date,
  formatPattern?:
    | 'MMM dd, yyyy HH:mm'
    | 'MMM dd, yyyy'
    | 'yyyy-MM-dd'
    | 'dd-MM-yyyy'
    | 'dd-MM-yyyy HH:mm:ss'
    | 'dd/MM/yyyy'
    | 'MM/dd/yyyy'
    | 'dd/MM/yyyy HH:mm'
    | 'MM/dd/yyyy HH:mm'
    | 'EEEE, MMMM dd, yyyy'
    | (string & {})
): string {
  try {
    if (!date) return '';
    return format(new Date(date), formatPattern || 'MMM dd, yyyy HH:mm');
  } catch (error) {
    console.error(error);
    throw error;
  }
}

