/**
 * Command filter comparison function for case-insensitive search
 * Used in Command components to filter options based on search input
 *
 * @param value - The value to search in
 * @param search - The user search query
 * @param keywords - Additional keywords to include in search
 * @returns 1 if match found, 0 otherwise
 */
export const compareSearching = (
  value: string | number | null | undefined,
  search: string | null | undefined,
  keywords?: string[]
): number => {
  const extendValue = removeVietnameseAccents(
    `${value} ${keywords?.join(' ') || ''}`
  ).toLowerCase();
  if (extendValue.includes(removeVietnameseAccents(search?.trim() || '').toLowerCase())) return 1;
  return 0;
};

export function formatCompact(value: number, decimals = 2): string {
  const absValue = Math.abs(value);
  const sign = value < 0 ? '-' : '';

  if (absValue >= 1_000_000_000_000_000) {
    return `${sign}${(absValue / 1_000_000_000_000_000).toFixed(decimals)}Q`;
  }
  if (absValue >= 1_000_000_000_000) {
    return `${sign}${(absValue / 1_000_000_000_000).toFixed(decimals)}T`;
  }
  if (absValue >= 1_000_000_000) {
    return `${sign}${(absValue / 1_000_000_000).toFixed(decimals)}B`;
  }
  if (absValue >= 1_000_000) {
    return `${sign}${(absValue / 1_000_000).toFixed(decimals)}M`;
  }
  if (absValue >= 1_000) {
    return `${sign}${(absValue / 1_000).toFixed(decimals)}k`;
  }

  return `${sign}${absValue.toFixed(decimals)}`;
}

export function toNumber(value: string | number | undefined | null): number {
  try {
    return Number(value);
  } catch (error) {
    console.error(error);
    return 0;
  }
}

/**
 * Convert a number to a percentage
 * @param value - The number to convert
 * @param precision - The number of decimal places to round to
 * @returns The percentage
 * @example
 * toPercentage(0.1) // 10
 * toPercentage(0.1234567890, 2) // 12.35
 * toPercentage(1) // 100
 * toPercentage(10, 2) // 1000.00
 */
export function toPercentage(
  value: number | string | undefined | null,
  precision?: number
): number {
  if (!value) return 0;
  return Number((toNumber(value) * 100).toFixed(precision ?? 2));
}

/**
 * Convert a percentage to a number
 * @param value - The percentage to convert
 * @param precision - The number of decimal places to round to
 * @returns The number
 * @example
 * fromPercentage(10) // 0.1
 * fromPercentage(100) // 1
 * fromPercentage(100, 2) // 1.00
 * fromPercentage(100.1234567890, 4) // 1.0012
 */
export function fromPercentage(
  value: number | string | undefined | null,
  precision?: number
): number {
  if (!value) return 0;
  return Number((toNumber(value) / 100).toFixed(precision ?? 2));
}

